-- Keep the public catalog intentionally broad. Existing listing references are
-- moved before the retired leaves are deprecated, so no listing becomes hidden.
UPDATE listings
SET category_id = CASE
    WHEN category_id IN (
        '01KCAT00000000000000000001','01KCAT00000000000000000002',
        '01KCAT00000000000000000003','01KCAT00000000000000000004',
        '01KCAT00000000000000000005','01KCAT00000000000000000006',
        '01KCAT00000000000000000007','01KCAT00000000000000000008',
        '01KCAT00000000000000000009','01KCAT0000000000000000000A',
        '01KCAT0000000000000000000B','01KCAT0000000000000000000C',
        '01KCAT0000000000000000000D'
    ) THEN '01K00000000000000000000002'
    WHEN category_id IN (
        '01KCAT0000000000000000000E','01KCAT0000000000000000000F',
        '01KCAT0000000000000000000G','01KCAT0000000000000000000H',
        '01KCAT0000000000000000000J','01KCAT0000000000000000000K',
        '01KCAT0000000000000000000M','01KCAT0000000000000000000N',
        '01KCAT0000000000000000000V'
    ) THEN '01K00000000000000000000003'
    WHEN category_id IN (
        '01KCAT0000000000000000000W','01KCAT0000000000000000000X',
        '01KCAT0000000000000000000Y','01KCAT0000000000000000000Z',
        '01KCAT00000000000000000010','01KCAT00000000000000000011'
    ) THEN '01K00000000000000000000004'
    WHEN category_id IN (
        '01KCAT00000000000000000014','01KCAT00000000000000000015',
        '01KCAT00000000000000000016','01KCAT00000000000000000017'
    ) THEN '01K00000000000000000000005'
    WHEN category_id = '01KCAT00000000000000000019'
        THEN '01KCAT0000000000000000000T'
    ELSE category_id
END
WHERE category_id IN (
    '01KCAT00000000000000000001','01KCAT00000000000000000002',
    '01KCAT00000000000000000003','01KCAT00000000000000000004',
    '01KCAT00000000000000000005','01KCAT00000000000000000006',
    '01KCAT00000000000000000007','01KCAT00000000000000000008',
    '01KCAT00000000000000000009','01KCAT0000000000000000000A',
    '01KCAT0000000000000000000B','01KCAT0000000000000000000C',
    '01KCAT0000000000000000000D','01KCAT0000000000000000000E',
    '01KCAT0000000000000000000F','01KCAT0000000000000000000G',
    '01KCAT0000000000000000000H','01KCAT0000000000000000000J',
    '01KCAT0000000000000000000K','01KCAT0000000000000000000M',
    '01KCAT0000000000000000000N','01KCAT0000000000000000000V',
    '01KCAT0000000000000000000W','01KCAT0000000000000000000X',
    '01KCAT0000000000000000000Y','01KCAT0000000000000000000Z',
    '01KCAT00000000000000000010','01KCAT00000000000000000011',
    '01KCAT00000000000000000014','01KCAT00000000000000000015',
    '01KCAT00000000000000000016','01KCAT00000000000000000017',
    '01KCAT00000000000000000019'
);

UPDATE categories
SET status = 'DEPRECATED',
    listing_creation_allowed = false,
    listing_submission_allowed = false,
    replacement_category_id = CASE
        WHEN id IN (
            '01KCAT00000000000000000001','01KCAT00000000000000000002',
            '01KCAT00000000000000000003','01KCAT00000000000000000004',
            '01KCAT00000000000000000005','01KCAT00000000000000000006',
            '01KCAT00000000000000000007','01KCAT00000000000000000008',
            '01KCAT00000000000000000009','01KCAT0000000000000000000A',
            '01KCAT0000000000000000000B','01KCAT0000000000000000000C',
            '01KCAT0000000000000000000D'
        ) THEN '01K00000000000000000000002'
        WHEN id IN (
            '01KCAT0000000000000000000E','01KCAT0000000000000000000F',
            '01KCAT0000000000000000000G','01KCAT0000000000000000000H',
            '01KCAT0000000000000000000J','01KCAT0000000000000000000K',
            '01KCAT0000000000000000000M','01KCAT0000000000000000000N',
            '01KCAT0000000000000000000V'
        ) THEN '01K00000000000000000000003'
        WHEN id IN (
            '01KCAT0000000000000000000W','01KCAT0000000000000000000X',
            '01KCAT0000000000000000000Y','01KCAT0000000000000000000Z',
            '01KCAT00000000000000000010','01KCAT00000000000000000011'
        ) THEN '01K00000000000000000000004'
        WHEN id IN (
            '01KCAT00000000000000000014','01KCAT00000000000000000015',
            '01KCAT00000000000000000016','01KCAT00000000000000000017'
        ) THEN '01K00000000000000000000005'
        ELSE '01KCAT0000000000000000000T'
    END,
    updated_at = current_timestamp(6)
WHERE id IN (
    '01KCAT00000000000000000001','01KCAT00000000000000000002',
    '01KCAT00000000000000000003','01KCAT00000000000000000004',
    '01KCAT00000000000000000005','01KCAT00000000000000000006',
    '01KCAT00000000000000000007','01KCAT00000000000000000008',
    '01KCAT00000000000000000009','01KCAT0000000000000000000A',
    '01KCAT0000000000000000000B','01KCAT0000000000000000000C',
    '01KCAT0000000000000000000D','01KCAT0000000000000000000E',
    '01KCAT0000000000000000000F','01KCAT0000000000000000000G',
    '01KCAT0000000000000000000H','01KCAT0000000000000000000J',
    '01KCAT0000000000000000000K','01KCAT0000000000000000000M',
    '01KCAT0000000000000000000N','01KCAT0000000000000000000V',
    '01KCAT0000000000000000000W','01KCAT0000000000000000000X',
    '01KCAT0000000000000000000Y','01KCAT0000000000000000000Z',
    '01KCAT00000000000000000010','01KCAT00000000000000000011',
    '01KCAT00000000000000000014','01KCAT00000000000000000015',
    '01KCAT00000000000000000016','01KCAT00000000000000000017',
    '01KCAT00000000000000000019'
);

UPDATE categories
SET name = 'Sports & Outdoors',
    description = 'Exercise, outdoor recreation, and sports equipment.',
    updated_at = current_timestamp(6)
WHERE id = '01KCAT0000000000000000000P';

UPDATE categories
SET name = 'Office & Crafts',
    description = 'Office supplies, stationery, art materials, craft supplies, and sewing products.',
    updated_at = current_timestamp(6)
WHERE id = '01KCAT0000000000000000000T';
